import type { Effect, Scope } from "effect"
import * as Hex from "../src/index.js"
import * as EffectHex from "../src/effect.js"

// Compile-only consumer checks: never start a helper from a type assertion.
export function createTypes(
  low: Hex.CreateOptions,
  ready: Hex.TranscriberOptions,
  ambiguous: Omit<Hex.CreateOptions, "model"> & { model?: Hex.ModelId },
) {
  const host: Promise<Hex.HexHost> = Hex.create(low)
  const transcriber: Promise<Hex.Transcriber> = Hex.create(ready)
  const effectHost: Effect.Effect<EffectHex.Host, EffectHex.HexError, Scope.Scope> = EffectHex.create(low)
  const effectTranscriber: Effect.Effect<EffectHex.Transcriber, EffectHex.HexError, Scope.Scope> = EffectHex.create(ready)
  const invalid = { model: "fictional-model" }

  // @ts-expect-error A model-bound transcriber cannot masquerade as a low-level host.
  const widened: Hex.CreateOptions = ready
  // @ts-expect-error Optional models cannot determine which resource is returned.
  Hex.create(ambiguous)
  // @ts-expect-error Optional models cannot determine which resource is returned.
  EffectHex.create(ambiguous)
  // @ts-expect-error Invalid model variables must not fall back to the low-level overload.
  Hex.create(invalid)
  // @ts-expect-error Invalid model variables must not fall back to the low-level overload.
  EffectHex.create(invalid)
  // @ts-expect-error The existing service layer deliberately provides only the low-level client.
  EffectHex.layer(ready)

  return { host, transcriber, effectHost, effectTranscriber, widened }
}

import { Effect } from "effect"
import { choice, defineHexConfig, digit, Hex, letter, press, text, union } from "../src/effect.js"

defineHexConfig({
  commands: {
    value: {
      phrases: ["effect value"],
      run: Effect.gen(function* () {
        const hex = yield* Hex
        yield* hex.typeText("value")
      }),
    },
    factory: {
      phrases: ["effect factory"],
      run: ({ context }) => Effect.gen(function* () {
        const hex = yield* Hex
        yield* hex.typeText(context.browserHost ?? "factory")
      }),
    },
    captures: {
      phrases: ["move {column} named {label}"],
      captures: {
        column: digit({ min: 1, max: 3 }),
        label: text(),
      },
      run: ({ captures }) => Effect.gen(function* () {
        const column: number = captures.column
        const label: string = captures.label
        const hex = yield* Hex
        yield* hex.typeText(`${column}:${label}`)
      }),
    },
    choice: {
      phrases: ["move {direction}"],
      captures: { direction: choice(["left", "right"] as const) },
      run: ({ captures }) => Effect.gen(function* () {
        const direction: "left" | "right" = captures.direction
        const hex = yield* Hex
        yield* hex.typeText(direction)
      }),
    },
    letter: {
      phrases: ["control {key}"],
      captures: { key: letter() },
      run: ({ captures }) => Effect.gen(function* () {
        const key: "a" | "b" | "c" | "d" | "e" | "f" | "g" | "h" | "i" | "j" | "k" | "l" | "m"
          | "n" | "o" | "p" | "q" | "r" | "s" | "t" | "u" | "v" | "w" | "x" | "y" | "z" = captures.key
        const hex = yield* Hex
        yield* hex.press({ key, modifiers: ["control"] })
      }),
    },
    union: {
      phrases: ["key {key}"],
      captures: { key: union(letter(), digit(), choice(["home", "escape"] as const)) },
      run: ({ captures }) => Effect.gen(function* () {
        const key: string | number = captures.key
        const hex = yield* Hex
        yield* hex.press(String(key))
      }),
    },
  },
})

defineHexConfig({
  commands: {
    invalidPromise: {
      phrases: ["invalid promise"],
      // @ts-expect-error Effect configs do not silently accept Promise handlers.
      run: async () => undefined,
    },
    invalidValue: {
      phrases: ["invalid value"],
      // @ts-expect-error Effect handlers must return an Effect.
      run: () => undefined,
    },
    invalidCapturedNativeAction: {
      phrases: ["control {number}"],
      captures: { number: digit() },
      // @ts-expect-error Typed captures require an Effect handler rather than a native run value.
      run: press("1"),
    },
  },
})

import { mkdtemp, readFile, rm } from "node:fs/promises"
import { tmpdir } from "node:os"
import { join } from "node:path"
import { ChildProcess } from "node:child_process"
import { once } from "node:events"
import { describe, expect, it, vi } from "vitest"
import { create, type ModelProgress } from "../src/index.js"
import { options, processIsAlive } from "./support.js"

describe("ready transcriber", () => {
  it("prepares once and binds the model and language across recordings", async () => {
    const progress: ModelProgress[] = []
    const requests: string[] = []
    const input = {
      ...options(), model: "parakeet_v2" as const, language: "en",
      onProgress: (event: ModelProgress) => { progress.push(event) },
      fetch: async (url: string | URL | Request, init?: RequestInit) => {
        requests.push(String(url))
        return fetch(url, init)
      },
    }
    const creating = create(input)
    input.language = "fr"
    const transcriber = await creating
    try {
      expect(progress.map((event) => event.type)).toEqual(["downloading", "verifying", "loading"])
      expect(transcriber.model).toBe("parakeet_v2")
      expect(transcriber.language).toBe("en")
      for (const audio of [new Uint8Array([1, 2, 3]), new ArrayBuffer(4)]) {
        expect(await transcriber.transcribe(audio)).toEqual({ transcript: "hello from hex", durationMs: 750 })
      }
      expect(requests.filter((url) => url.includes("/prepare"))).toHaveLength(1)
      expect(requests.filter((url) => url.includes("/transcriptions")).map((url) => new URL(url).search))
        .toEqual(["?model=parakeet_v2&language=en", "?model=parakeet_v2&language=en"])
    } finally {
      await transcriber.close()
    }
    await transcriber.close()
    expect(processIsAlive(transcriber.pid)).toBe(false)
    await expect(transcriber.transcribe(new Uint8Array(4))).rejects.toMatchObject({ code: "service-exited" })
  })

  it.each(["error", "cancel", "callback"])("closes the helper before failed creation settles: %s", async (mode) => {
    const directory = await mkdtemp(join(tmpdir(), "hex-ready-"))
    const pidPath = join(directory, "pid")
    const controller = new AbortController()
    try {
      await expect(create({
        ...options(), model: "parakeet_v2",
        env: { HEX_FAKE_PID_PATH: pidPath, HEX_FAKE_PREPARE_ERROR: "1" },
        signal: controller.signal,
        onProgress: () => {
          if (mode === "cancel") controller.abort()
          if (mode === "callback") throw new Error("UI callback failed")
        },
      })).rejects.toMatchObject({
        code: mode === "error" ? "model-prepare-failed" : mode === "cancel" ? "cancelled" : "request-failed",
      })
      expect(processIsAlive(Number(await readFile(pidPath, "utf8")))).toBe(false)
    } finally {
      await rm(directory, { recursive: true, force: true })
    }
  })

  it("does not close a ready transcriber for an already-aborted request", async () => {
    const transcriber = await create({ ...options(), model: "parakeet_v2" })
    try {
      await expect(transcriber.transcribe(new Uint8Array(4), { signal: AbortSignal.abort() }))
        .rejects.toMatchObject({ code: "cancelled" })
      expect(processIsAlive(transcriber.pid)).toBe(true)
      expect((await transcriber.transcribe(new Uint8Array(4))).transcript).toBe("hello from hex")
    } finally {
      await transcriber.close()
    }
  })

  it("does not let buffered success overtake cancellation", async () => {
    const controller = new AbortController()
    const transcriber = await create({
      ...options(), model: "parakeet_v2",
      fetch: async (url, init) => {
        const response = await fetch(url, init)
        if (String(url).includes("/transcriptions")) {
          const json = response.json.bind(response)
          response.json = async () => {
            const result: unknown = await json()
            controller.abort()
            return result
          }
        }
        return response
      },
    })
    try {
      await expect(transcriber.transcribe(new Uint8Array(4), { signal: controller.signal }))
        .rejects.toMatchObject({ code: "cancelled" })
      expect(processIsAlive(transcriber.pid)).toBe(false)
    } finally {
      await transcriber.close()
    }
  })

  it("reports failed startup cleanup instead of implying the child stopped", async () => {
    const children: ChildProcess[] = []
    const kill = vi.spyOn(ChildProcess.prototype, "kill").mockImplementation(function (this: ChildProcess) {
      children.push(this)
      throw new Error("Termination denied")
    })
    try {
      await expect(create({
        ...options(), model: "parakeet_v2", shutdownTimeoutMs: 1,
        env: { HEX_FAKE_MODE: "bad-handshake", HEX_FAKE_IGNORE_LEASE: "1" },
      })).rejects.toMatchObject({ code: "shutdown-failed" })
    } finally {
      kill.mockRestore()
      for (const child of children) {
        if (child.exitCode !== null || child.signalCode !== null) continue
        const exited = once(child, "exit")
        child.kill("SIGKILL")
        await exited
      }
    }
  })

  it.each(["abort", "close", "replaced-signal"])("waits for native ownership to end on %s", async (mode) => {
    let markStarted = () => {}
    const started = new Promise<void>((resolve) => { markStarted = resolve })
    const controller = new AbortController()
    const transcriber = await create({
      ...options(), model: "parakeet_v2",
      env: { HEX_FAKE_TRANSCRIBE_HANG: "1" },
      fetch: async (url, init) => {
        const response = await fetch(url, init)
        if (String(url).includes("/transcriptions")) markStarted()
        return response
      },
    })
    try {
      const request = { signal: controller.signal }
      const result = expect(transcriber.transcribe(new Uint8Array(4), request))
        .rejects.toMatchObject({ code: mode === "close" ? "service-exited" : "cancelled" })
      await started
      if (mode === "replaced-signal") request.signal = new AbortController().signal
      if (mode === "close") void transcriber.close()
      else controller.abort()
      await result
      expect(processIsAlive(transcriber.pid)).toBe(false)
    } finally {
      await transcriber.close()
    }
  })

  it("keeps the helper alive after an ordinary request failure", async () => {
    const transcriber = await create({
      ...options(), model: "parakeet_v2", env: { HEX_FAKE_TRANSCRIBE_ERROR: "1" },
    })
    try {
      await expect(transcriber.transcribe(new Uint8Array(4)))
        .rejects.toMatchObject({ code: "request-failed", remoteCode: "model-not-ready" })
      expect(processIsAlive(transcriber.pid)).toBe(true)
    } finally {
      await transcriber.close()
    }
  })

  it("settles every pending request when one cancellation closes their helper", async () => {
    let markStarted = () => {}
    const started = new Promise<void>((resolve) => { markStarted = resolve })
    let uploads = 0
    const controller = new AbortController()
    const transcriber = await create({
      ...options(), model: "parakeet_v2", env: { HEX_FAKE_TRANSCRIBE_HANG: "1" },
      fetch: async (url, init) => {
        const response = await fetch(url, init)
        if (String(url).includes("/transcriptions") && ++uploads === 2) markStarted()
        return response
      },
    })
    try {
      const first = expect(transcriber.transcribe(new Uint8Array(4), { signal: controller.signal }))
        .rejects.toMatchObject({ code: "cancelled" })
      const second = expect(transcriber.transcribe(new Uint8Array(4)))
        .rejects.toMatchObject({ code: "service-exited" })
      await started
      controller.abort()
      await Promise.all([first, second])
      expect(processIsAlive(transcriber.pid)).toBe(false)
    } finally {
      await transcriber.close()
    }
  })
})

import { describe, expect, it } from "vitest"
import {
  choice,
  defineHexConfig,
  digit,
  letter,
  openApplication,
  openPath,
  openUrl,
  press,
  typeText,
  text,
  union,
} from "../src/index.js"

describe("command model", () => {
  it("builds every native descriptor", () => {
    expect(openUrl("https://example.com")).toEqual({ type: "openUrl", url: "https://example.com" })
    expect(openApplication("Slack")).toEqual({ type: "openApplication", application: "Slack" })
    expect(openPath("/tmp/example")).toEqual({ type: "openPath", path: "/tmp/example" })
    expect(press("escape")).toEqual({ type: "press", key: "escape" })
    expect(press({ key: "p", modifiers: ["command", "shift"], repeat: 2 })).toEqual({
      type: "press",
      key: "p",
      modifiers: ["command", "shift"],
      repeat: 2,
    })
    expect(typeText("fixed text")).toEqual({ type: "typeText", text: "fixed text" })
  })

  it("preserves normal TypeScript record composition", () => {
    const navigation = {
      home: { phrases: ["open home"] as const, action: openUrl("https://example.com") },
    }
    const config = defineHexConfig({
      transformations: {
        lowercase: {
          name: "Lowercase",
          transform: (text) => text.toLowerCase(),
        },
      },
      dictation: {
        start: ["begin note"],
        stop: ["finish note"],
        send: ["send note"],
        cancel: ["discard note"],
      },
      commands: {
        ...navigation,
        slack: { phrases: ["open slack"], run: openApplication("Slack") },
      },
    })
    expect(Object.keys(config.commands)).toEqual(["home", "slack"])
    expect(config.dictation.send).toEqual(["send note"])
    expect(config.transformations.lowercase.transform("HELLO")).toBe("hello")
  })

  it("contextually types Promise handlers through the shared config model", () => {
    const config = defineHexConfig({
      commands: {
        contextual: {
          phrases: ["show context"],
          run: ({ hex, context }) => hex.typeText(context.browserHost ?? "none"),
        },
      },
    })

    expect(config.commands.contextual!.phrases).toEqual(["show context"])
  })

  it("infers exact typed capture values from descriptors", () => {
    const config = defineHexConfig({
      commands: {
        range: {
          phrases: ["move {column} to {row} then {note}"],
          captures: {
            column: digit({ min: 1, max: 3 }),
            row: digit({ min: 4, max: 9 }),
            note: text(),
          },
          run: ({ captures }) => {
            expectTypeOf(captures).toEqualTypeOf<Readonly<{
              column: number
              row: number
              note: string
            }>>()
          },
        },
      },
    })

    expect(config.commands.range!.captures!.column).toEqual({ type: "digit", min: 1, max: 3 })
    expect(config.commands.range!.captures!.note).toEqual({ type: "text" })
  })

  it("defaults digit captures to zero through nine", () => {
    expect(digit()).toEqual({ type: "digit", min: 0, max: 9 })
  })

  it("infers the exact lowercase letter union", () => {
    const config = defineHexConfig({
      commands: {
        control: {
          phrases: ["control {key}"],
          captures: { key: letter() },
          run: ({ captures }) => {
            expectTypeOf(captures.key).toEqualTypeOf<
              "a" | "b" | "c" | "d" | "e" | "f" | "g" | "h" | "i" | "j" | "k" | "l" | "m"
              | "n" | "o" | "p" | "q" | "r" | "s" | "t" | "u" | "v" | "w" | "x" | "y" | "z"
            >()
          },
        },
      },
    })

    expect(config.commands.control!.captures!.key).toEqual({ type: "letter" })
  })

  it("infers choice literals from arrays and canonical object keys", () => {
    const config = defineHexConfig({
      commands: {
        direction: {
          phrases: ["move {direction}"],
          captures: { direction: choice(["left", "right"] as const) },
          run: ({ captures }) => {
            expectTypeOf(captures.direction).toEqualTypeOf<"left" | "right">()
          },
        },
        navigation: {
          phrases: ["go {direction}"],
          captures: {
            direction: choice({
              left: ["left", "back"],
              right: ["right", "forward"],
            } as const),
          },
          run: ({ captures }) => {
            expectTypeOf(captures.direction).toEqualTypeOf<"left" | "right">()
          },
        },
      },
    })

    expect(config.commands.direction!.captures!.direction).toEqual({
      type: "choice",
      choices: { left: ["left"], right: ["right"] },
    })
    expect(config.commands.navigation!.captures!.direction.choices.left).toEqual(["left", "back"])
  })

  it("builds flattened unions and infers every member value", () => {
    const nested = union(digit(), choice(["home", "end"] as const))
    const key = union(letter(), nested, choice(["enter", "escape"] as const))
    const config = defineHexConfig({
      commands: {
        key: {
          phrases: ["key {key}"],
          captures: { key },
          run: ({ captures }) => {
            expectTypeOf(captures.key).toEqualTypeOf<
              | "a" | "b" | "c" | "d" | "e" | "f" | "g" | "h" | "i" | "j" | "k" | "l" | "m"
              | "n" | "o" | "p" | "q" | "r" | "s" | "t" | "u" | "v" | "w" | "x" | "y" | "z"
              | number | "home" | "end" | "enter" | "escape"
            >()
          },
        },
      },
    })

    expect(key.members).toHaveLength(4)
    expect(key.members.map((member) => member.type)).toEqual(["letter", "digit", "choice", "choice"])
    expect(config.commands.key!.captures!.key).toBe(key)
  })

  it("rejects invalid and internally overlapping unions", () => {
    expect(() => union(letter(), choice(["alpha"]))).toThrow("overlap")
    expect(() => union(digit(), choice(["two"]))).toThrow("overlap")
    expect(() => union(letter(), text() as never)).toThrow("does not accept text")
    expect(() => union(...Array.from({ length: 17 }, (_, index) => choice([`key${index}`])) as [ReturnType<typeof choice>, ReturnType<typeof choice>, ...ReturnType<typeof choice>[]]))
      .toThrow("at most 16")
    if (false) {
      // @ts-expect-error A union requires at least two bounded members.
      union(letter())
      // @ts-expect-error text() is not a bounded one-token capture.
      union(letter(), text())
    }
  })

  it("requires handlers for schema-bearing commands", () => {
    defineHexConfig({
      commands: {
        invalid: {
          phrases: ["control {number}"],
          captures: { number: digit({ min: 1, max: 3 }) },
          // @ts-expect-error Typed captures require a run handler.
          action: press("1"),
        },
        invalidRun: {
          phrases: ["control {number}"],
          captures: { number: digit({ min: 1, max: 3 }) },
          // @ts-expect-error Typed captures require a handler rather than a native run value.
          run: press("1"),
        },
      },
    })
  })
})

import { Deferred, Effect, Fiber, Stream } from "effect"
import { watch } from "node:fs"
import { mkdtemp, readFile, rm, writeFile } from "node:fs/promises"
import { tmpdir } from "node:os"
import { join } from "node:path"
import { describe, expect, it } from "vitest"
import * as Hex from "../src/effect.js"
import { options, processIsAlive } from "./support.js"

describe("Effect client", () => {
  it("creates a ready transcriber with scope-owned cleanup", async () => {
    let pid = 0
    const progress: string[] = []
    const result = await Effect.runPromise(Effect.scoped(Effect.gen(function* () {
      const transcriber = yield* Hex.create({
        ...options(), model: "parakeet_v2", language: "en",
        onProgress: (event) => { progress.push(event.type) },
      })
      pid = transcriber.pid
      expect(transcriber.language).toBe("en")
      return yield* transcriber.transcribe(new Uint8Array([1, 2, 3]))
    })))
    expect(result.transcript).toBe("hello from hex")
    expect(progress).toEqual(["downloading", "verifying", "loading"])
    expect(processIsAlive(pid)).toBe(false)
  })

  it("interrupts model preparation and waits for helper cleanup", async () => {
    const directory = await mkdtemp(join(tmpdir(), "hex-effect-ready-"))
    const pidPath = join(directory, "pid")
    let markStarted = () => {}
    const started = new Promise<void>((resolve) => { markStarted = resolve })
    try {
      await Effect.runPromise(Effect.scoped(Effect.gen(function* () {
        const fiber = yield* Hex.create({
          ...options(), model: "parakeet_v2",
          env: { HEX_FAKE_PID_PATH: pidPath, HEX_FAKE_PREPARE_HANG: "1" },
          shutdownTimeoutMs: 100,
          onProgress: markStarted,
        }).pipe(Effect.forkScoped)
        yield* Effect.promise(() => started)
        yield* Fiber.interrupt(fiber)
        const pid = yield* Effect.promise(() => readFile(pidPath, "utf8"))
        expect(processIsAlive(Number(pid))).toBe(false)
      })))
    } finally {
      await rm(directory, { recursive: true, force: true })
    }
  })

  it("waits for interrupted inference to stop even while the owning scope stays open", async () => {
    let markStarted = () => {}
    const started = new Promise<void>((resolve) => { markStarted = resolve })
    await Effect.runPromise(Effect.scoped(Effect.gen(function* () {
      const transcriber = yield* Hex.create({
        ...options(), model: "parakeet_v2", shutdownTimeoutMs: 100,
        env: { HEX_FAKE_TRANSCRIBE_HANG: "1" },
        fetch: async (url, init) => {
          const response = await fetch(url, init)
          if (String(url).includes("/transcriptions")) markStarted()
          return response
        },
      })
      const fiber = yield* transcriber.transcribe(new Uint8Array(4)).pipe(Effect.forkScoped)
      yield* Effect.promise(() => started)
      yield* Fiber.interrupt(fiber)
      expect(processIsAlive(transcriber.pid)).toBe(false)
    })))
  })

  it("cleans up pending startup interruption before returning to an open parent scope", async () => {
    const directory = await mkdtemp(join(tmpdir(), "hex-effect-start-"))
    const pidPath = join(directory, "pid")
    const gate = join(directory, "handshake")
    const watcher = watch(directory)
    const started = new Promise<void>((resolve) => {
      watcher.on("change", (_event, file) => {
        if (file === "pid") resolve()
      })
    })
    try {
      await Effect.runPromise(Effect.scoped(Effect.gen(function* () {
        const fiber = yield* Hex.create({
          ...options(), model: "parakeet_v2",
          env: { HEX_FAKE_PID_PATH: pidPath, HEX_FAKE_HANDSHAKE_GATE: gate },
        }).pipe(Effect.forkScoped)
        yield* Effect.promise(() => started)
        fiber.interruptUnsafe()
        yield* Effect.promise(() => writeFile(gate, "ready"))
        yield* Fiber.interrupt(fiber)
        const pid = yield* Effect.promise(() => readFile(pidPath, "utf8"))
        expect(processIsAlive(Number(pid))).toBe(false)
      })))
    } finally {
      watcher.close()
      await rm(directory, { recursive: true, force: true })
    }
  })

  it.each([
    Hex.StartupError,
    Hex.ProtocolError,
    Hex.RequestError,
    Hex.ModelPreparationError,
    Hex.CancellationError,
  ])("preserves tagged error fields and yieldable failures for %s", async (ErrorClass) => {
    const cause = new Error("underlying failure")
    const error = new ErrorClass({ code: "test-failure", message: "operation failed", cause })
    expect(error).toBeInstanceOf(Error)
    expect(error._tag).toBe(`Hex.${ErrorClass.name}`)
    expect(error.message).toBe("operation failed")
    expect(error.cause).toBe(cause)
    const failure = await Effect.runPromise(Effect.gen(function* () {
      return yield* error
    }).pipe(Effect.flip))
    expect(failure).toBe(error)
  })

  it("scopes the helper and exposes Effect and Stream operations", async () => {
    let pid = 0
    const result = await Effect.runPromise(Effect.scoped(Effect.gen(function* () {
      const host = yield* Hex.create(options())
      pid = host.pid
      const health = yield* host.client.health()
      const progress = yield* host.client.models.prepare("parakeet_v2", { language: "en" }).pipe(
        Stream.runCollect,
      )
      const transcript = yield* host.client.transcribe({
        audio: { data: new Uint8Array([1, 2, 3]), contentType: "audio/wav" },
        model: "parakeet_v2",
      })
      return { health, progress: Array.from(progress, (event) => event.type), transcript }
    })))

    expect(result).toEqual({
      health: { version: "test", apiVersion: "2" },
      progress: ["downloading", "verifying", "loading"],
      transcript: { transcript: "hello from hex", durationMs: 750 },
    })
    expect(processIsAlive(pid)).toBe(false)
  })

  it("provides the client as a scoped service layer", async () => {
    const health = await Effect.runPromise(
      Effect.gen(function* () {
        const hex = yield* Hex.Service
        return yield* hex.health()
      }).pipe(Effect.provide(Hex.layer(options()))),
    )

    expect(health.version).toBe("test")
  })

  it("interrupts an in-flight preparation when its stream scope closes", async () => {
    let pid = 0
    let requestSignal: AbortSignal | null | undefined
    await Effect.runPromise(Effect.scoped(Effect.gen(function* () {
      const host = yield* Hex.create({
        ...options(),
        env: { HEX_FAKE_PREPARE_HANG: "1" },
        fetch: (url, init) => {
          if (String(url).includes("/prepare")) requestSignal = init?.signal
          return fetch(url, init)
        },
      })
      pid = host.pid
      const progress = yield* Deferred.make<void>()
      const fiber = yield* host.client.models.prepare("parakeet_v2").pipe(
        Stream.tap(() => Deferred.succeed(progress, undefined)),
        Stream.runDrain,
        Effect.forkScoped,
      )
      yield* Deferred.await(progress)
      yield* Fiber.interrupt(fiber)
      expect(requestSignal?.aborted).toBe(true)
      expect(processIsAlive(host.pid)).toBe(true)
      expect((yield* host.client.health()).apiVersion).toBe("2")
    })))

    expect(processIsAlive(pid)).toBe(false)
  })

  it("preserves typed preparation failures through the progress stream", async () => {
    await Effect.runPromise(Effect.scoped(Effect.gen(function* () {
      const host = yield* Hex.create({ ...options(), env: { HEX_FAKE_PREPARE_ERROR: "1" } })
      const error = yield* host.client.models.prepare("parakeet_v2").pipe(Stream.runDrain, Effect.flip)
      expect(error).toMatchObject({
        _tag: "Hex.ModelPreparationError", code: "model-prepare-failed", remoteCode: "load-failed",
      })
      expect(processIsAlive(host.pid)).toBe(true)
    })))
  })
})

import { Deferred, Effect } from "effect"
import { describe, expect, it } from "vitest"
import { Hex } from "../src/effect.js"
import { choice, digit, letter, openUrl, text, union } from "../src/index.js"
import type { HandlerArguments, Letter } from "../src/index.js"
import { prepareConfig, runHost } from "../src/host.js"
import type { HostOutput } from "../src/protocol.js"

async function* messages(lines: readonly unknown[]): AsyncGenerator<string> {
  for (const line of lines) yield `${JSON.stringify(line)}\n`
}

describe("command host", () => {
  it("emits a bounded serializable registration without handlers", () => {
    const prepared = prepareConfig({
      dictation: {
        start: ["begin note"],
        stop: ["finish note"],
        send: ["send note"],
        cancel: ["discard note"],
      },
      commands: {
        native: { phrases: ["open example"], action: openUrl("https://example.com") },
        handled: { phrases: ["do work"], group: "Work", run: () => undefined },
      },
    })
    expect(prepared.registration).toEqual({
      type: "registration",
      protocolVersion: 2,
      dictation: {
        start: ["begin note"],
        stop: ["finish note"],
        send: ["send note"],
        cancel: ["discard note"],
      },
      transformations: [],
      commands: [
        {
          id: "native",
          phrases: ["open example"],
          execution: { type: "native", action: { type: "openUrl", url: "https://example.com" } },
        },
        {
          id: "handled",
          phrases: ["do work"],
          group: "Work",
          execution: { type: "handler" },
        },
      ],
    })
    expect(() => JSON.stringify(prepared.registration)).not.toThrow()
  })

  it("registers and applies ordered transformations", async () => {
    const output: HostOutput[] = []
    await runHost({
      config: {
        transformations: {
          trim: { name: "Trim", transform: (text: string) => text.trim() },
          lowercase: {
            name: "Lowercase",
            description: "Use lowercase output",
            transform: async (text: string) => text.toLowerCase(),
          },
        },
        commands: {},
      },
      input: messages([
        {
          type: "transform",
          invocationId: "transform-1",
          transformationIds: ["trim", "lowercase"],
          text: "  HELLO  ",
          context: { application: "Messages" },
        },
        { type: "shutdown" },
      ]),
      write: (frame) => { output.push(frame) },
    })

    expect(output[0]).toMatchObject({
      type: "registration",
      transformations: [
        { id: "trim", name: "Trim" },
        { id: "lowercase", name: "Lowercase", description: "Use lowercase output" },
      ],
    })
    expect(output[1]).toEqual({
      type: "transformationResult",
      invocationId: "transform-1",
      result: { type: "success", text: "hello" },
    })
  })

  it.each([
    "https://example.com",
    "slack://channel?team=T_EXAMPLE&id=C_EXAMPLE",
  ])("adapts vanilla handlers and round-trips %s", async (url) => {
    const output: HostOutput[] = []
    let observedApplication: string | undefined
    await runHost({
      config: {
        commands: {
          example: {
            phrases: ["open example"],
            run: async ({ hex, context }: HandlerArguments) => {
              observedApplication = context.application
              await hex.openUrl(url)
            },
          },
        },
      },
      input: messages([
        {
          type: "invoke",
          invocationId: "inv-1",
          commandId: "example",
          context: { application: "Brave Browser", browserUrl: "https://example.com/page" },
        },
        {
          type: "toolResult",
          invocationId: "inv-1",
          toolCallId: "1",
          result: { type: "success" },
        },
        { type: "shutdown" },
      ]),
      write: (frame) => { output.push(frame) },
    })
    expect(output.map((frame) => frame.type)).toEqual([
      "registration",
      "toolCall",
      "invocationResult",
    ])
    expect(output[1]).toEqual({
      type: "toolCall",
      invocationId: "inv-1",
      toolCallId: "1",
      action: { type: "openUrl", url },
    })
    expect(observedApplication).toBe("Brave Browser")
  })

  it("passes bounded captures to vanilla and Effect handlers", async () => {
    const output: HostOutput[] = []
    const observedCaptures: Readonly<Record<string, string>>[] = []
    let observedEffectCaptures: Readonly<Record<string, string | number>> | undefined
    await runHost({
      config: {
        commands: {
          search: {
            phrases: ["search amazon for {query}"],
            run: async ({ captures }: HandlerArguments) => {
              observedCaptures.push(captures)
            },
          },
          note: {
            phrases: ["note {text}"],
            run: Effect.gen(function* () {
              const hex = yield* Hex
              observedEffectCaptures = hex.captures
            }),
          },
        },
      },
      input: messages([
        {
          type: "invoke",
          invocationId: "inv-1",
          commandId: "search",
          context: {},
          captures: { query: "wool socks" },
        },
        { type: "invoke", invocationId: "inv-2", commandId: "note", context: {}, captures: { text: "buy socks" } },
        { type: "invoke", invocationId: "inv-3", commandId: "search", context: {} },
        { type: "shutdown" },
      ]),
      write: (frame) => { output.push(frame) },
    })
    expect(output.filter((frame) => frame.type === "invocationResult")).toHaveLength(3)
    expect(observedCaptures).toEqual([{ query: "wool socks" }, {}])
    expect(observedEffectCaptures).toEqual({ text: "buy socks" })
  })

  it("registers typed capture schemas and passes numeric values", async () => {
    const output: HostOutput[] = []
    let observed: number | undefined
    await runHost({
      config: {
        commands: {
          control: {
            phrases: ["control {number}"],
            captures: { number: digit({ min: 1, max: 3 }) },
            run: ({ captures }: HandlerArguments<{ readonly number: number }>) => {
              observed = captures.number
            },
          },
        },
      },
      input: messages([
        { type: "invoke", invocationId: "inv-1", commandId: "control", context: {}, captures: { number: 2 } },
        { type: "shutdown" },
      ]),
      write: (frame) => { output.push(frame) },
    })

    expect(output[0]).toMatchObject({
      protocolVersion: 2,
      commands: [{ captures: { number: { type: "digit", min: 1, max: 3 } } }],
    })
    expect(observed).toBe(2)
