  it("normalizes choice aliases and passes only canonical values", async () => {
    const output: HostOutput[] = []
    let observed: { direction: "left" | "right"; edge: "top" | "bottom" } | undefined
    await runHost({
      config: {
        commands: {
          move: {
            phrases: ["move {direction} {edge}"],
