      write: (frame) => { output.push(frame) },
    })

    expect(output[0]).toMatchObject({
      protocolVersion: 2,
      commands: [{
        captures: {
          direction: {
            type: "choice",
            choices: { left: ["left", "back"], right: ["right", "forward"] },
          },
          edge: { type: "choice", choices: { top: ["top"], bottom: ["bottom"] } },
        },
      }],
