      result: { type: "failure", message: "Command key received invalid captures" },
    })
  })

  it("validates typed capture schemas and every alias binding", () => {
    expect(prepareConfig({
      commands: {
        nested: {
          phrases: ["key {key}"],
          captures: { key: {
            type: "union",
            members: [
              { type: "letter" },
              { type: "union", members: [
                { type: "digit", min: 0, max: 9 },
                { type: "choice", choices: { home: ["home"] } },
              ] },
